package com.pridesys.ticketing.users.service;
import com.pridesys.ticketing.dto.*; import com.pridesys.ticketing.entity.*; import com.pridesys.ticketing.repository.UserRepository; import org.springframework.data.domain.PageRequest; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.util.*;
@Service public class UserManagementService { private final UserRepository users; private final PasswordEncoder encoder; public UserManagementService(UserRepository u,PasswordEncoder e){users=u;encoder=e;} public List<AuthDtos.ProfileResponse> list(UserEntity actor,String q,int page,int size){requireAdmin(actor);int limit=Math.min(Math.max(1,size),100);return users.search(q,PageRequest.of(Math.max(0,page),limit)).getContent().stream().filter(u->visible(actor,u)).map(this::profile).toList();} public AuthDtos.ProfileResponse create(UserEntity actor,CreateUser req){requireAdmin(actor);if(actor.getRole()==UserRole.CLIENT_ADMIN&&req.role()==UserRole.APP_ADMIN)throw new AccessDeniedException("Insufficient role");Long client=req.clientId();if(actor.getRole()!=UserRole.APP_ADMIN){client=actor.getClientId();if(req.clientId()!=null&&!req.clientId().equals(client))throw new AccessDeniedException("Outside client scope");}var u=new UserEntity(req.email().trim().toLowerCase(),encoder.encode("Password123!"),req.role(),req.name().trim(),client);return profile(users.save(u));}public void deactivate(UserEntity actor,long id){requireAdmin(actor);target(actor,id).setActive(false);users.save(target(actor,id));}public AuthDtos.ProfileResponse update(UserEntity actor,long id,UsersProjectsDtos.UpdateUserRequest r){requireAdmin(actor);var u=target(actor,id);u.setName(r.name().trim());u.setMobile(r.mobile());u.setDesignation(r.designation());u.setOffice(r.office());if(r.active()!=null)u.setActive(r.active());return profile(users.save(u));}private boolean visible(UserEntity a,UserEntity u){return a.getRole()==UserRole.APP_ADMIN||Objects.equals(a.getClientId(),u.getClientId());}private UserEntity target(UserEntity a,long id){var u=users.findById(id).orElseThrow();if(!visible(a,u)||a.getRole()==UserRole.CLIENT_ADMIN&&u.getRole()==UserRole.APP_ADMIN)throw new AccessDeniedException("Outside client scope");return u;}private void requireAdmin(UserEntity a){if(a.getRole()==UserRole.CLIENT_USER)throw new AccessDeniedException("Insufficient role");}private AuthDtos.ProfileResponse profile(UserEntity u){return new AuthDtos.ProfileResponse(u.getId(),u.getEmail(),u.getRole().name(),u.getName(),u.getMobile(),u.getDesignation(),u.getOffice(),u.isActive());}public record CreateUser(String email,String name,UserRole role,Long clientId){} }
